// Normaliza dados brutos do Apify para o schema leads_outbound
const items = $input.all();
const leads = [];

for (const item of items) {
  const d = item.json;
  if (!d || typeof d !== 'object') continue;

  // Extrai e normaliza telefone
  const rawPhone = d.phone || d.internationalPhoneNumber || '';
  const digits   = rawPhone.replace(/\D/g, '');

  let phone = '';
  if (digits.startsWith('55') && digits.length >= 12) {
    phone = digits;
  } else if (digits.length === 11 || digits.length === 10) {
    phone = '55' + digits;
  } else if (digits.length > 0) {
    phone = '55' + digits.slice(-11);
  }

  if (!phone || phone.length < 12) continue;

  // Extrai localização
  const address  = d.address || d.formattedAddress || '';
  const stateMap = {
    'São Paulo': 'SP', 'Rio de Janeiro': 'RJ', 'Minas Gerais': 'MG',
    'Goiás': 'GO', 'Distrito Federal': 'DF'
  };

  let city  = d.city || '';
  let state = d.state || '';

  if (!city && address) {
    const parts = address.split(',').map(p => p.trim());
    if (parts.length >= 3) city = parts[parts.length - 3] || '';
  }
  if (!state) {
    for (const [name, abbr] of Object.entries(stateMap)) {
      if (address.includes(name) || address.includes(abbr)) { state = abbr; break; }
    }
  }

  // Classifica sinais de dor
  const painSignals = [];
  if (!d.website && !d.url)       painSignals.push('sem_site');
  if ((d.reviewsCount || 0) < 10) painSignals.push('poucos_reviews');
  if ((d.totalScore   || 0) < 4)  painSignals.push('nota_baixa');
  painSignals.push('sem_verificacao_ads');

  leads.push({
    json: {
      source:               'google_maps',
      niche:                'advocacia',
      business_name:        d.title || d.name || 'Desconhecido',
      category:             (d.categories || []).join(', ') || 'Advocacia',
      city:                 city  || 'N/A',
      state:                state || 'N/A',
      address:              address,
      phone:                phone,
      whatsapp:             phone,
      website:              d.website || null,
      instagram_handle:     null,
      google_rating:        d.totalScore        || null,
      google_reviews_count: d.reviewsCount       || null,
      google_maps_url:      d.url               || null,
      has_website:          !!(d.website),
      pain_signals:         JSON.stringify(painSignals),
      raw_data:             JSON.stringify(d)
    }
  });
}

console.log('Leads válidos:', leads.length);
return leads;
